function validate([time]) {
  if (typeof time !== 'string' || time.length !== 5) return 'time must have exactly 5 characters, like "09:05".';
  if (!/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(time)) return 'time must be a valid "HH:MM" reading from 00:00 to 23:59.';
  return null;
}

