function nextClosestTime(time) {
  const digits = [...new Set(time.replace(':', ''))];
  const start = Number(time.slice(0, 2)) * 60 + Number(time.slice(3));
  let answer = time;
  let bestGap = 24 * 60;

  for (const h1 of digits) {
    for (const h2 of digits) {
      for (const m1 of digits) {
        for (const m2 of digits) {
          const hours = Number(h1 + h2);
          const minutes = Number(m1 + m2);
          if (hours >= 24 || minutes >= 60) {
            continue;
          }
          const total = hours * 60 + minutes;
          let gap = (total - start + 24 * 60) % (24 * 60);
          if (gap === 0) {
            gap = 24 * 60;
          }
          if (gap < bestGap) {
            bestGap = gap;
            answer = h1 + h2 + ':' + m1 + m2;
          }
        }
      }
    }
  }
  return answer;
}

