function nextClosestTime(time) {
  // Walk the clock forward one minute at a time until every digit shown is allowed.
  const allowed = new Set(time);
  let clock = Number(time.slice(0, 2)) * 60 + Number(time.slice(3));
  for (let step = 0; step < 1440; step++) {
    clock = (clock + 1) % 1440;
    const text = String(Math.floor(clock / 60)).padStart(2, '0') + ':' + String(clock % 60).padStart(2, '0');
    if ([...text].every(c => allowed.has(c))) return text;
  }
  return null;
}

