function generate(rand, size) {
  const pad = v => String(v).padStart(2, '0');
  if (size === 'small' && rand() < 0.5) {
    // Few distinct digits make wrap-arounds and "same time" answers common.
    const pool = [];
    const k = 1 + Math.floor(rand() * 3);
    for (let i = 0; i < k; i++) pool.push(Math.floor(rand() * 6));
    for (;;) {
      const d = () => pool[Math.floor(rand() * pool.length)];
      const hours = d() * 10 + d();
      const minutes = d() * 10 + Math.floor(rand() * 10);
      if (hours < 24 && minutes < 60) return [pad(hours) + ':' + pad(minutes)];
      if (rand() < 0.2) return [pad(Math.floor(rand() * 24)) + ':' + pad(Math.floor(rand() * 60))];
    }
  }
  return [pad(Math.floor(rand() * 24)) + ':' + pad(Math.floor(rand() * 60))];
}
